class AsyncAssetsClient:
    def __init__(self, *, client_wrapper: AsyncClientWrapper):
        self._raw_client = AsyncRawAssetsClient(client_wrapper=client_wrapper)

    @property
    def with_raw_response(self) -> AsyncRawAssetsClient:
        """
        Retrieves a raw implementation of this client that returns raw responses.

        Returns
        -------
        AsyncRawAssetsClient
        """
        return self._raw_client

    async def list(
        self,
        *,
        limit: typing.Optional[int] = None,
        offset: typing.Optional[int] = None,
        filters: typing.Optional[str] = None,
        sort: typing.Optional[str] = None,
        workspace_id: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> PaginatedAssetsOut:
        """
        Retrieve a paginated list of assets with optional filtering and sorting. Assets include documents, presentations, spreadsheets, images, videos, and other file types managed by Athena Intelligence.

        Parameters
        ----------
        limit : typing.Optional[int]
            Maximum number of assets to return per page (1-500)

        offset : typing.Optional[int]
            Number of assets to skip for pagination

        filters : typing.Optional[str]
            JSON string of filter criteria. Supports: created_by_id, created_by_email, tags, created_after/before, updated_after/before, title_substring, is_archived, is_hidden, athena_metadata, media_type, athena_converted_type, athena_original_type, summary_ready, summary_status, workspace_id

        sort : typing.Optional[str]
            JSON string of sort criteria: [{"field": "updated_at", "direction": "desc"}]. Supported fields: created_by_id, created_by_email, created_at, updated_at, is_archived, is_hidden, summary_ready, summary_status

        workspace_id : typing.Optional[str]
            Workspace to list assets from. Caller must be a member.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        PaginatedAssetsOut
            Successfully retrieved paginated list of assets

        Examples
        --------
        import asyncio

        from athena import AsyncAthena

        client = AsyncAthena(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.assets.list(
                limit=50,
                offset=0,
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.list(
            limit=limit,
            offset=offset,
            filters=filters,
            sort=sort,
            workspace_id=workspace_id,
            request_options=request_options,
        )
        return _response.data

    async def convert_excel_to_sheet(
        self,
        *,
        excel_asset_id: str,
        password: typing.Optional[str] = OMIT,
        run_async: typing.Optional[bool] = OMIT,
        spreadsheet_engine: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ConvertExcelToSheetResponseOut:
        """
        Convert an uploaded Excel (.xlsx) asset into a new, editable Athena sheet asset — the same conversion the Athena UI performs. The new sheet is created alongside the source Excel asset. Pass run_async for large workbooks to get the sheet immediately and poll athena_metadata.conversionStatus for completion.

        Parameters
        ----------
        excel_asset_id : str
            ID of the Excel (.xlsx) asset to convert into an Athena sheet

        password : typing.Optional[str]
            Optional password used to decrypt a password-protected workbook. Password-protected workbooks always convert on the 'legacy' engine.

        run_async : typing.Optional[bool]
            Return the sheet asset immediately and convert in the background. Large workbooks outlive the gateway's ~60s response window on the synchronous path — with run_async the caller polls athena_metadata.conversionStatus ('converting' | 'completed' | 'failed', with conversionError on failure) instead.

        spreadsheet_engine : typing.Optional[str]
            Engine for the converted sheet ('rnc' | 'legacy'). Defaults to the deployment's default engine.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ConvertExcelToSheetResponseOut
            Excel asset converted successfully

        Examples
        --------
        import asyncio

        from athena import AsyncAthena

        client = AsyncAthena(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.assets.convert_excel_to_sheet(
                excel_asset_id="asset_92492920-d118-42d3-95b4-00eccfe0754f",
                run_async=False,
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.convert_excel_to_sheet(
            excel_asset_id=excel_asset_id,
            password=password,
            run_async=run_async,
            spreadsheet_engine=spreadsheet_engine,
            request_options=request_options,
        )
        return _response.data

    async def create(
        self,
        *,
        asset_type: CreatableAssetType,
        parent_folder_id: typing.Optional[str] = OMIT,
        title: typing.Optional[str] = OMIT,
        workspace_id: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CreateAssetResponseOut:
        """
        Create a new asset such as a spreadsheet, document, folder, database, computer, or generic doc (admin-only) in your workspace. This endpoint uses internal GraphQL mutations to create assets with proper permissions and workspace integration. Computer assets return 202 after the initializing asset is committed; runtime provisioning continues asynchronously.

        Parameters
        ----------
        asset_type : CreatableAssetType
            Type of asset to create. Supported types: 'spreadsheet' (or 'sheet'), 'document' (or 'doc'), 'folder', 'database' (or 'db'), 'computer'

        parent_folder_id : typing.Optional[str]
            ID of the parent folder to create the asset in

        title : typing.Optional[str]
            Title for the new asset

        workspace_id : typing.Optional[str]
            ID of the workspace to create the asset in. If not provided, the asset is created in the user's current workspace. The user must be a member of the specified workspace.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CreateAssetResponseOut
            Asset created successfully

        Examples
        --------
        import asyncio

        from athena import AsyncAthena

        client = AsyncAthena(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.assets.create(
                asset_type="spreadsheet",
                parent_folder_id="asset_folder_12345",
                title="My New Spreadsheet",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create(
            asset_type=asset_type,
            parent_folder_id=parent_folder_id,
            title=title,
            workspace_id=workspace_id,
            request_options=request_options,
        )
        return _response.data

    async def create_project(
        self,
        *,
        title: str,
        custom_metadata: typing.Optional[typing.Dict[str, typing.Optional[typing.Any]]] = OMIT,
        description: typing.Optional[str] = OMIT,
        parent_folder_id: typing.Optional[str] = OMIT,
        project_type: typing.Optional[str] = OMIT,
        share_with_emails: typing.Optional[typing.Sequence[str]] = OMIT,
        tags: typing.Optional[typing.Sequence[str]] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> CreateProjectResponseOut:
        """
        Create a new project with custom metadata. Projects can be typed (e.g., 'candidate', 'user', 'company') and include flexible custom metadata for storing additional information.

        Parameters
        ----------
        title : str
            The project title

        custom_metadata : typing.Optional[typing.Dict[str, typing.Optional[typing.Any]]]
            A flexible dictionary for storing custom metadata

        description : typing.Optional[str]
            Optional project description

        parent_folder_id : typing.Optional[str]
            Optional parent folder ID

        project_type : typing.Optional[str]
            User-defined project type (e.g., 'candidate', 'user', 'company')

        share_with_emails : typing.Optional[typing.Sequence[str]]
            Optional list of email addresses to share the project with (VIEW permission)

        tags : typing.Optional[typing.Sequence[str]]
            Optional list of tags for categorizing the project

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        CreateProjectResponseOut
            Project created successfully

        Examples
        --------
        import asyncio

        from athena import AsyncAthena

        client = AsyncAthena(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.assets.create_project(
                custom_metadata={
                    "email": "john.doe@example.com",
                    "phone": "+1-555-0123",
                    "source": "linkedin",
                    "status": "active",
                },
                description="Candidate profile for senior software engineer position",
                parent_folder_id="asset_folder_123",
                project_type="candidate",
                share_with_emails=["colleague@example.com", "manager@example.com"],
                tags=["engineering", "senior", "active"],
                title="John Doe - Software Engineer",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create_project(
            title=title,
            custom_metadata=custom_metadata,
            description=description,
            parent_folder_id=parent_folder_id,
            project_type=project_type,
            share_with_emails=share_with_emails,
            tags=tags,
            request_options=request_options,
        )
        return _response.data

    async def duplicate(
        self,
        *,
        source_asset_id: str,
        parent_folder_id: typing.Optional[str] = OMIT,
        workspace_id: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> DuplicateAssetResponseOut:
        """
        Duplicate an asset using the same duplication service used by the Athena UI. Optionally target a workspace and/or destination folder.

        Parameters
        ----------
        source_asset_id : str
            ID of the asset to duplicate

        parent_folder_id : typing.Optional[str]
            Optional destination folder for the duplicated asset

        workspace_id : typing.Optional[str]
            Workspace to create the duplicate in. If omitted, the source asset's workspace is used.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        DuplicateAssetResponseOut
            Asset duplicated successfully

        Examples
        --------
        import asyncio

        from athena import AsyncAthena

        client = AsyncAthena(
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.assets.duplicate(
                parent_folder_id="asset_folder_12345",
                source_asset_id="asset_92492920-d118-42d3-95b4-00eccfe0754f",
                workspace_id="workspace_abc123",
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.duplicate(
            source_asset_id=source_asset_id,
            parent_folder_id=parent_folder_id,
            workspace_id=workspace_id,
            request_options=request_options,
        )
        return _response.data

